-- Account-scoped Vault lifecycle. Decrypted values are never selected by customer roles.
create or replace function public.store_phase_n_customer_credentials(p_customer_id uuid,p_account_id uuid,p_provider text,p_secret_json text,p_identity text,p_capabilities jsonb)
returns uuid language plpgsql security definer set search_path=public,vault,extensions as $$declare a connected_execution_accounts;ref uuid;begin
 if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;
 select * into a from connected_execution_accounts where id=p_account_id and customer_id=p_customer_id for update;
 if not found or lower(a.provider)<>lower(p_provider) then raise exception 'ACCOUNT_PROVIDER_OWNERSHIP_REQUIRED';end if;
 if not ((lower(p_provider)='binance' and lower(a.environment)='testnet') or (lower(p_provider)='bybit' and lower(a.environment)='demo')) then raise exception 'SANDBOX_ENVIRONMENT_REQUIRED';end if;
 if coalesce((p_capabilities->>'withdrawal')::boolean,true) or not coalesce((p_capabilities->>'trading')::boolean,false) then raise exception 'UNSAFE_CREDENTIAL_CAPABILITIES';end if;
 if a.credential_ref is null then select vault.create_secret(p_secret_json,concat('phase-n-account-',p_account_id::text),'Account-scoped sandbox credential') into ref;update connected_execution_accounts set credential_ref=ref::text,provider_account_identity=p_identity,credentials_verified_at=now(),provider_health='healthy',updated_at=now() where id=a.id;
 else ref:=a.credential_ref::uuid;perform vault.update_secret(ref,p_secret_json);update connected_execution_accounts set provider_account_identity=p_identity,credentials_verified_at=now(),provider_health='healthy',updated_at=now() where id=a.id;end if;
 update provider_connections set secret_reference=ref::text,external_fingerprint=encode(extensions.digest(p_identity,'sha256'),'hex'),capabilities=p_capabilities,state='VERIFIED',last_verified_at=now(),safe_error_code=null,updated_at=now() where execution_account_id=a.id and customer_id=a.customer_id;
 insert into phase_h_audit_events(customer_id,execution_account_id,event_type,safe_metadata) values(a.customer_id,a.id,'CRYPTO_CREDENTIAL_VERIFIED',jsonb_build_object('provider',upper(p_provider),'withdrawal',false));return ref;end$$;
revoke all on function public.store_phase_n_customer_credentials(uuid,uuid,text,text,text,jsonb) from public,anon,authenticated;grant execute on function public.store_phase_n_customer_credentials(uuid,uuid,text,text,text,jsonb) to service_role;

create or replace function public.revoke_phase_n_customer_credentials(p_customer_id uuid,p_account_id uuid) returns boolean language plpgsql security definer set search_path=public,vault,extensions as $$declare ref uuid;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select credential_ref::uuid into ref from connected_execution_accounts where id=p_account_id and customer_id=p_customer_id for update;if not found then raise exception 'ACCOUNT_OWNERSHIP_REQUIRED';end if;if ref is not null then perform vault.delete_secret(ref);end if;update connected_execution_accounts set credential_ref=null,credentials_verified_at=null,provider_health='not_configured',execution_enabled=false,updated_at=now() where id=p_account_id;update provider_connections set secret_reference=null,state='DISCONNECTED',capabilities='{}',updated_at=now() where execution_account_id=p_account_id and customer_id=p_customer_id;return true;end$$;
revoke all on function public.revoke_phase_n_customer_credentials(uuid,uuid) from public,anon,authenticated;grant execute on function public.revoke_phase_n_customer_credentials(uuid,uuid) to service_role;
